            // TODO API_TEST_START
            int expectedColor = 0xFF123456;
            int watermarkSize = 10;
            int insets = 5;

            java.awt.image.BufferedImage watermarkImg = new java.awt.image.BufferedImage(
                watermarkSize, watermarkSize, java.awt.image.BufferedImage.TYPE_INT_ARGB);
            java.awt.Graphics2D g2d = watermarkImg.createGraphics();
            g2d.setColor(new java.awt.Color(expectedColor, true));
            g2d.fillRect(0, 0, watermarkSize, watermarkSize);
            g2d.dispose();

            net.coobird.thumbnailator.filters.Watermark watermark = new net.coobird.thumbnailator.filters.Watermark(
                net.coobird.thumbnailator.geometry.Positions.BOTTOM_RIGHT, 
